SELECT LI.LSTG_ID, LI.MBR_CD, LI.LSTG_ADD, LI.LSTG_LAT, LI.LSTG_LNG, LI.LSTG_NM, LI.LSTG_EX_AREA, LI.LSTG_GR_AREA, LI.LSTG_TYPE_SALE, LI.LSTG_LEASE, LI.LSTG_LEASE_M, LI.LSTG_LEASE_AMT, LI.LSTG_FLOOR, LI.LSTG_PARK_YN, LI.LSTG_TYPE_CODE1, LI.LSTG_TYPE_CODE2, LI.LSTG_POSTAL, (SELECT COUNT(*) FROM LISTING_WISHLIST W WHERE W.LSTG_ID = LI.LSTG_ID AND W.MBR_CD = #{mbrCd}) AS wishCount FROM LISTING LI WHERE LI.LSTG_LAT BETWEEN #{swLat} AND #{neLat} AND LI.LSTG_LNG BETWEEN #{swLng} AND #{neLng}
AND LI.LSTG_TYPE_CODE1 IN
#{type}
AND LI.LSTG_TYPE_CODE2 IN
#{type}
AND LI.LSTG_TYPE_SALE IN
#{type}
AND LI.lstg_type_code1 = #{category}
AND ( LI.LSTG_ADD LIKE CONCAT('%', #{keyword}, '%') OR LI.LSTG_ADD2 LIKE CONCAT('%', #{keyword}, '%') OR LI.LSTG_GR_AREA LIKE CONCAT('%',#{keyword}, '%') OR LI.LSTG_NM LIKE CONCAT('%', #{keyword}, '%') )
AND EXISTS ( SELECT 1 FROM LISTING_OPTION LOP WHERE LOP.LSTG_ID = LI.LSTG_ID AND LOP.FAC_OPT_ID IN
#{opt}
)
